 const monitor=async(id:string,status:'ACTIVE'|'PAUSED'|'COMPLETED'|'CANCELLED')=>{try{setBusy(true);const r=await fetch(API+`/api/owner/ads/campaigns/${id}/status`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({status})});const d=await r.json();if(!r.ok)throw Error(d.error||'Falha');setMsg('✓ Estado da campanha atualizado.');await load()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}};
