 const load=async()=>{try{setMsg('');const headers={Authorization:`Bearer ${token}`};const from=new Date(Date.now()-(range-1)*86400000).toISOString().slice(0,10),to=new Date().toISOString().slice(0,10);const [d,f,a,p]=await Promise.all([fetch(API+'/api/owner/dashboard',{headers}),fetch(API+'/api/admin/finance/summary',{headers}),fetch(API+`/api/admin/analytics/streams?from=${from}&to=${to}`,{headers}),fetch(API+'/api/admin/releases/pending',{headers})]);const dd=await d.json(),fd=await f.json(),ad=await a.json(),pd=await p.json();if(d.ok)setDashboard(dd);if(f.ok)setFinance(fd);if(a.ok)setAnalytics(ad.analytics);if(p.ok)setPending(pd.releases||[]);if(!d.ok||!f.ok||!a.ok)setMsg(dd.error||fd.error||ad.error||'Não foi possível carregar os dados.')}catch(e:any){setMsg(e.message||'Erro de ligação')}};
