 const daily=analytics?.daily||[]; const maxDaily=Math.max(1,...daily.map((x:any)=>Number(x.streams||0))); const chartW=700,chartH=230; const points=daily.length?daily.map((x:any,i:number)=>{const xx=daily.length===1?chartW/2:(i/(daily.length-1))*chartW;const yy=chartH-(Number(x.streams||0)/maxDaily)*(chartH-28)-8;return `${xx},${yy}`}).join(' '):'';
